def get_supported_kernel_block_sizes() -> list[int | MultipleOf]:
    # QSA consumes manager pages directly and does not use FA4 paged attention.
    return [MultipleOf(16)]

def _resolve_gdn_prefill_backend(
    vllm_config: VllmConfig,
) -> tuple[str, Literal["triton", "flashinfer", "cutedsl"]]:
    """Resolve GDN prefill backend.

    FlashInfer's GDN prefill kernel is chosen when:
    * ``requested in ["flashinfer", "auto"]``;
    * ``platform == cuda``;
    * one of the following:
      - Hopper (SM90) — no further constraints;
      - Blackwell (SM10.x) with ``head_k_dim == 128``, ``cuda_runtime >= 13``.

    In-tree CuteDSL GDN prefill kernel is chosen when:
    * "cutedsl" is requested; (opt-in only)
    * Blackwell (SM10.x) with ``head_k_dim == 128``;
    """
    additional_config = vllm_config.additional_config
    backend_cfg = (
        additional_config.get("gdn_prefill_backend", "auto")
        if isinstance(additional_config, dict)
        else "auto"
    )
    backend = str(backend_cfg).strip().lower()

    if not current_platform.is_cuda():
        return backend, "triton"

    head_k_dim = getattr(
        vllm_config.model_config.hf_text_config, "linear_key_head_dim", None
    )

    supports_flashinfer = False
    supports_cutedsl = False

    if current_platform.is_device_capability(90):
        supports_flashinfer = True
    elif (
        current_platform.is_device_capability_family(100)
        and head_k_dim == 128
        and current_platform.get_cuda_runtime_major() >= 13
    ):
        supports_flashinfer = True
        supports_cutedsl = True

    if backend in ["flashinfer", "auto"] and supports_flashinfer:
        return backend, "flashinfer"
    if backend == "cutedsl" and supports_cutedsl:
        return backend, "cutedsl"
    return backend, "triton"

def _supports_current_device() -> bool:
    """Supports only Blackwell-family GPUs."""
    p = current_platform
    return (
        p.is_cuda()
        and p.is_device_capability_family(100)
        and has_flashinfer_trtllm_fused_moe()
    )

def _supports_parallel_config(moe_parallel_config: FusedMoEParallelConfig) -> bool:
    """Monolithic kernel so only use with naive DP/EP and TP."""
    return (
        not moe_parallel_config.use_all2all_kernels
        or moe_parallel_config.use_ag_rs_all2all_kernels
    ) and not (
        moe_parallel_config.enable_eplb or moe_parallel_config.is_sequence_parallel
    )

def _supports_parallel_config(moe_parallel_config: FusedMoEParallelConfig) -> bool:
    return (
        not moe_parallel_config.use_all2all_kernels
        or moe_parallel_config.use_ag_rs_all2all_kernels
        or moe_parallel_config.use_deepep_v2_kernels
        or moe_parallel_config.use_fi_nvl_one_sided_kernels
        or moe_parallel_config.use_fi_nvl_two_sided_kernels
    ) and not moe_parallel_config.enable_eplb

def _supports_quant_scheme(
    weight_key: QuantKey | None,
    activation_key: QuantKey | None,
) -> bool:
    """Supports Fp8 block and MXFP8."""
    SUPPORTED_W_A = [
        (kFp8Static128BlockSym, kFp8Dynamic128Sym),
        (kMxfp8Static, kMxfp8Dynamic),
    ]
    return (weight_key, activation_key) in SUPPORTED_W_A

def _supports_current_device() -> bool:
    p = current_platform
    return (
        p.is_cuda()
        and (
            p.is_device_capability(90)
            or p.is_device_capability_family(100)
            # SM110 excluded: flashinfer-ai/flashinfer#3134
            or p.is_device_capability_family(120)
        )
        and has_flashinfer_cutlass_fused_moe()
    )

def _supports_quant_scheme(
    weight_key: QuantKey | None,
    activation_key: QuantKey | None,
) -> bool:
    SUPPORTED_W_A = [
        (kFp8StaticChannelSym, kFp8DynamicTokenSym),
        (kFp8StaticTensorSym, kFp8DynamicTensorSym),
        (kFp8StaticTensorSym, kFp8StaticTensorSym),
    ]
    return (weight_key, activation_key) in SUPPORTED_W_A

def _supports_parallel_config(moe_parallel_config: FusedMoEParallelConfig) -> bool:
    # CutlassExpertsFp8 does not support expert map, which is
    # needed for STANDARD activation format kernels in DP/EP mode.
    # Note that the BATCHED activation format does not use
    # the expert map for identifying experts.
    return not (
        moe_parallel_config.use_fi_nvl_two_sided_kernels
        or moe_parallel_config.use_deepep_ht_kernels
        or moe_parallel_config.use_fi_nvl_one_sided_kernels
    )

def _supports_current_device() -> bool:
    p = current_platform
    return p.is_cuda() and (
        p.is_device_capability_family(100)
        or p.is_device_capability_family(110)
        or p.is_device_capability_family(120)
    )

def _supports_quant_scheme(
    weight_key: QuantKey | None,
    activation_key: QuantKey | None,
) -> bool:
    return (weight_key, activation_key) == (kNvfp4Static, kNvfp4Dynamic)

def _supports_current_device() -> bool:
    p = current_platform
    capability = p.get_device_capability()
    return (
        p.is_cuda()
        and capability is not None
        and ops.mxfp4_experts_quant_supported(capability.to_int())
    )

